const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define area near Damietta Nile mouth
  const damiettaloc = ee.Geometry.Point([31.8, 31.5]).buffer(5000);

  // Cloud masking for Landsat 5
  function maskL5sr(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0)
                   .and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(mask);
  }

  // Cloud masking for Landsat 8
  function maskL8sr(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0)
                   .and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(mask);
  }

  // Get 1984 data (Landsat 5)
  let col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(damiettaloc)
    .filter(ee.Filter.calendarRange(1984, 1984, 'year'))
    .filter(ee.Filter.calendarRange(6, 8, 'month'))
    .map(maskL5sr);

  const size1984 = await col1984.size().getInfo();
  console.log(`1984 Images found: ${size1984}`);

  if (size1984 === 0) {
    console.log("No images for 1984");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get 2021 data (Landsat 8)
  let col2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(damiettaloc)
    .filter(ee.Filter.calendarRange(2021, 2021, 'year'))
    .filter(ee.Filter.calendarRange(6, 8, 'month'))
    .map(maskL8sr);

  const size2021 = await col2021.size().getInfo();
  console.log(`2021 Images found: ${size2021}`);

  if (size2021 === 0) {
    console.log("No images for 2021");
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate NDVI for 1984
  const img1984 = col1984.median();
  const ndvi1984 = img1984.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');

  // Calculate NDVI for 2021
  const img2021 = col2021.median();
  const ndvi2021 = img2021.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');

  // Check valid pixels for 1984
  const count1984 = await ndvi1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: damiettaloc,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`1984 Valid pixels: ${count1984}`);

  if (count1984 === 0) {
    console.log("No valid pixels for 1984");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check valid pixels for 2021
  const count2021 = await ndvi2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: damiettaloc,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`2021 Valid pixels: ${count2021}`);

  if (count2021 === 0) {
    console.log("No valid pixels for 2021");
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean NDVI
  const mean1984 = await ndvi1984.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: damiettaloc,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const mean2021 = await ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: damiettaloc,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`1984 Mean NDVI: ${mean1984}`);
  console.log(`2021 Mean NDVI: ${mean2021}`);

  // Validate results
  if (mean1984 === null || mean2021 === null || isNaN(mean1984) || isNaN(mean2021)) {
    console.log("Calculation failed - invalid values");
    console.log("<answer>C3</answer>");
    return;
  }

  if (mean1984 < -1 || mean1984 > 1 || mean2021 < -1 || mean2021 > 1) {
    console.log("NDVI out of valid range");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare vegetation cover
  if (mean1984 > mean2021) {
    console.log("1984 vegetation cover was greater than 2021");
    console.log("<answer>A</answer>");
  } else {
    console.log("1984 vegetation cover was NOT greater than 2021");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
